package com.cattlefarm.admin.platform;
import cn.dev33.satoken.stp.StpUtil;import com.baomidou.mybatisplus.core.toolkit.IdWorker;import com.cattlefarm.admin.auth.service.AuthService;import com.cattlefarm.admin.common.DataConflictException;import org.springframework.dao.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service
public class PlatformService{
 private final JdbcTemplate jdbc;private final AuthService auth;public PlatformService(JdbcTemplate jdbc,AuthService auth){this.jdbc=jdbc;this.auth=auth;}
 public PlatformDtos.Farm farm(){long id=auth.currentFarmId();return jdbc.queryForObject("SELECT * FROM farm WHERE farm_id=?",(r,n)->new PlatformDtos.Farm(s(r.getLong("farm_id")),r.getString("farm_name"),r.getString("farm_code"),r.getString("farm_type"),r.getString("contact_name"),r.getString("contact_phone"),r.getString("status"),r.getString("remark"),r.getInt("version")),id);}
 @Transactional public PlatformDtos.Farm updateFarm(PlatformDtos.UpdateFarm r,String key){long farm=auth.currentFarmId(),user=user();String path="/api/v1/farm";Long old=replay(farm,user,key,path);if(old!=null)return farm();idem(farm,user,key,path,farm);int n=jdbc.update("UPDATE farm SET farm_name=?,contact_name=?,contact_phone=?,remark=?,version=version+1 WHERE farm_id=? AND version=?",r.farmName().trim(),r.contactName(),r.contactPhone(),r.remark(),farm,r.version());if(n==0)throw new DataConflictException("牛场资料已被其他人修改，请刷新后重试");audit(farm,user,"FARM_UPDATED","FARM",farm,"更新牛场资料");return farm();}
 public List<PlatformDtos.Rule>rules(){long farm=auth.currentFarmId();return jdbc.query("SELECT * FROM system_param WHERE farm_id=? ORDER BY param_code",(r,n)->new PlatformDtos.Rule(r.getString("param_code"),r.getString("param_name"),r.getString("param_value"),r.getString("value_type"),r.getString("remark")),farm);}
 @Transactional public List<PlatformDtos.Rule>updateRules(PlatformDtos.UpdateRules r,String key){long farm=auth.currentFarmId(),user=user();String path="/api/v1/settings/business-rules";Long old=replay(farm,user,key,path);if(old!=null)return rules();for(var e:r.values().entrySet()){Integer exists=jdbc.queryForObject("SELECT COUNT(*) FROM system_param WHERE farm_id=? AND param_code=?",Integer.class,farm,e.getKey());if(exists==null||exists==0)throw new DataConflictException("未知业务规则："+e.getKey());int value;try{value=Integer.parseInt(e.getValue());}catch(Exception x){throw new DataConflictException("业务规则必须是整数："+e.getKey());}if(value<1||value>365)throw new DataConflictException("业务规则数值必须在 1 到 365 之间");}idem(farm,user,key,path,farm);r.values().forEach((code,value)->jdbc.update("UPDATE system_param SET param_value=? WHERE farm_id=? AND param_code=?",value,farm,code));audit(farm,user,"BUSINESS_RULES_UPDATED","SYSTEM_PARAM",farm,"更新业务规则参数");return rules();}
 public PlatformDtos.Dashboard dashboard(){long f=auth.currentFarmId();return new PlatformDtos.Dashboard(count("SELECT COUNT(*) FROM cattle WHERE farm_id=? AND presence_status='IN_FIELD'",f),count("SELECT COUNT(*) FROM task WHERE farm_id=? AND status IN('PENDING','IN_PROGRESS')",f),count("SELECT COUNT(*) FROM task WHERE farm_id=? AND (status='OVERDUE' OR (status IN('PENDING','IN_PROGRESS') AND due_date<CURDATE()))",f),count("SELECT COUNT(*) FROM cattle WHERE farm_id=? AND presence_status='IN_FIELD' AND health_status<>'NORMAL'",f),count("SELECT COUNT(*) FROM cattle WHERE farm_id=? AND presence_status='IN_FIELD' AND breeding_status='PREGNANT'",f),count("SELECT COUNT(*) FROM pregnancy_check WHERE farm_id=? AND is_void=0 AND check_result='POSITIVE' AND expected_calving_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 14 DAY)",f),count("SELECT COUNT(DISTINCT t.cattle_id) FROM treatment_record t JOIN medication_item m ON m.treatment_id=t.treatment_id AND m.farm_id=t.farm_id WHERE t.farm_id=? AND t.is_void=0 AND m.withdrawal_days>0 AND DATE_ADD(DATE(t.treatment_date),INTERVAL m.withdrawal_days DAY)>=CURDATE()",f),count("SELECT COUNT(*) FROM mixing_order WHERE farm_id=? AND feed_date=CURDATE() AND status IN('PENDING_CONFIRM','CONFIRMED')",f));}
 public List<PlatformDtos.DictType>types(){return jdbc.query("SELECT * FROM dict_type WHERE status='ENABLED' ORDER BY type_code",(r,n)->new PlatformDtos.DictType(s(r.getLong("dict_type_id")),r.getString("type_code"),r.getString("type_name"),r.getString("status")));}public List<PlatformDtos.DictItem>items(String type){long farm=auth.currentFarmId();return jdbc.query("SELECT i.*,t.type_code FROM dict_item i JOIN dict_type t ON t.dict_type_id=i.dict_type_id WHERE t.type_code=? AND (i.farm_id IS NULL OR i.farm_id=?) ORDER BY i.sort_no,i.item_name",(r,n)->new PlatformDtos.DictItem(s(r.getLong("dict_item_id")),r.getString("type_code"),r.getString("item_code"),r.getString("item_name"),r.getInt("sort_no"),r.getString("status"),r.getString("remark")),type,farm);}
 @Transactional public PlatformDtos.DictItem createItem(PlatformDtos.CreateDictItem r,String key){long farm=auth.currentFarmId(),user=user();String path="/api/v1/dictionaries/entries";Long old=replay(farm,user,key,path);if(old!=null)return item(old);Long type=typeId(r.typeCode());long id=IdWorker.getId();idem(farm,user,key,path,id);try{jdbc.update("INSERT INTO dict_item(dict_item_id,dict_type_id,farm_id,item_code,item_name,sort_no,remark) VALUES(?,?,?,?,?,?,?)",id,type,farm,r.itemCode(),r.itemName().trim(),r.sortNo()==null?0:r.sortNo(),r.remark());}catch(DuplicateKeyException e){throw new DataConflictException("同类字典编码不能重复");}audit(farm,user,"DICT_ITEM_CREATED","DICT_ITEM",id,"创建业务字典项");return item(id);}
 @Transactional public PlatformDtos.DictItem updateItem(long id,PlatformDtos.UpdateDictItem r,String key){long farm=auth.currentFarmId(),user=user();String path="/api/v1/dictionaries/entries/"+id;Long old=replay(farm,user,key,path);if(old!=null)return item(old);PlatformDtos.DictItem before=item(id);idem(farm,user,key,path,id);int n=jdbc.update("UPDATE dict_item SET item_name=?,status=?,sort_no=?,remark=? WHERE dict_item_id=? AND farm_id=?",r.itemName().trim(),r.status(),r.sortNo()==null?before.sortNo():r.sortNo(),r.remark(),id,farm);if(n==0)throw new DataConflictException("系统默认字典项不可修改");audit(farm,user,"DICT_ITEM_UPDATED","DICT_ITEM",id,"更新业务字典项");return item(id);}
 private PlatformDtos.DictItem item(long id){long farm=auth.currentFarmId();try{return jdbc.queryForObject("SELECT i.*,t.type_code FROM dict_item i JOIN dict_type t ON t.dict_type_id=i.dict_type_id WHERE i.dict_item_id=? AND (i.farm_id IS NULL OR i.farm_id=?)",(r,n)->new PlatformDtos.DictItem(s(id),r.getString("type_code"),r.getString("item_code"),r.getString("item_name"),r.getInt("sort_no"),r.getString("status"),r.getString("remark")),id,farm);}catch(EmptyResultDataAccessException e){throw new DataConflictException("字典项不存在");}}private Long typeId(String code){try{return jdbc.queryForObject("SELECT dict_type_id FROM dict_type WHERE type_code=? AND status='ENABLED'",Long.class,code);}catch(EmptyResultDataAccessException e){throw new DataConflictException("字典类型不存在");}}private long count(String sql,Object...a){Number n=jdbc.queryForObject(sql,Number.class,a);return n==null?0:n.longValue();}private void audit(long f,long u,String a,String t,long id,String reason){jdbc.update("INSERT INTO operation_log(operation_log_id,farm_id,user_id,module_code,action_type,business_type,business_id,reason) VALUES(?,?,?,'SYSTEM',?,?,?,?)",IdWorker.getId(),f,u,a,t,id,reason);}private void idem(long f,long u,String k,String p,long id){jdbc.update("INSERT INTO idempotency_record(farm_id,user_id,idempotency_key,request_path,business_id,expires_at) VALUES(?,?,?,?,?,?)",f,u,k,p,id,LocalDateTime.now().plusDays(1));}private Long replay(long f,long u,String k,String p){try{return jdbc.queryForObject("SELECT business_id FROM idempotency_record WHERE farm_id=? AND user_id=? AND idempotency_key=? AND request_path=? AND expires_at>NOW()",Long.class,f,u,k,p);}catch(EmptyResultDataAccessException e){return null;}}private long user(){return StpUtil.getLoginIdAsLong();}private static String s(long id){return Long.toString(id);}
}
